def is_spanish():
    return bool(st.session_state.get("spanish_ui", False))


@lru_cache(maxsize=1)
def _pattern():
    alternatives = sorted(SPANISH, key=len, reverse=True)
    return re.compile(r"(?<!\w)(?:" + "|".join(
        r"\s+".join(re.escape(part) for part in key.split()) for key in alternatives) + r")(?!\w)")


def tr(value, spanish=None):
    """Translate display text while retaining HTML, code, URLs, and citations."""
    if not isinstance(value, str) or not (is_spanish() if spanish is None else spanish):
        return value
    if "<style>" in value:
        return value
    # Bibliographic titles remain exactly as published; only translate the heading.
    if 'class="reference-box"' in value:
        return value.replace("Source:", "Fuente:")
    protected = re.split(r"(<[^>]*>|`[^`]*`|https?://[^\s<)]+)", value)
    for index in range(0, len(protected), 2):
        protected[index] = _pattern().sub(lambda match: SPANISH[" ".join(match.group(0).split())], protected[index])
    return "".join(protected)


def localized_formatter(formatter=None):
    # Streamlit may invoke formatters outside the script thread (for example in
    # widget serialization). Capture the render language, not mutable session state.
    spanish = is_spanish()
    return lambda value: tr(formatter(value) if formatter else value, spanish=spanish)


def localized_dataframe(data):
    if not is_spanish() or not isinstance(data, pd.DataFrame):
        return data
    display = data.copy()
    display.columns = [tr(column) for column in display.columns]
    for column in display.columns:
        if pd.api.types.is_object_dtype(display[column]) or pd.api.types.is_string_dtype(display[column]):
            display[column] = display[column].map(tr)
    return display


def localized_figure(figure):
    if not is_spanish() or figure is None:
        return figure
    payload = figure.to_plotly_json()
    text_fields = {"text", "name", "hovertemplate", "hovertext", "ticktext", "labels"}

    def visit(value, key=None):
        if isinstance(value, dict):
            return {field: visit(item, field) for field, item in value.items()}
        if isinstance(value, (list, tuple)):
            return [visit(item, key) for item in value]
        return tr(value) if key in text_fields else value

    return go.Figure(visit(payload))
